module protocol::interest;

use math::float::{Self, Decimal};

public struct InterestModel has copy, drop, store {
    base_borrow_rate_per_sec: Decimal,
    borrow_rate_on_mid_kink: Decimal,
    mid_kink: Decimal,
    borrow_rate_on_high_kink: Decimal,
    high_kink: Decimal,
    max_borrow_rate: Decimal,
}

public(package) fun base_borrow_rate(model: &InterestModel): Decimal { model.base_borrow_rate_per_sec }
public(package) fun borrow_rate_on_mid_kink(model: &InterestModel): Decimal { model.borrow_rate_on_mid_kink}
public(package) fun mid_kink(model: &InterestModel): Decimal { model.mid_kink }
public(package) fun borrow_rate_on_high_kink(model: &InterestModel): Decimal { model.borrow_rate_on_high_kink }
public(package) fun high_kink(model: &InterestModel): Decimal { model.high_kink }
public(package) fun max_borrow_rate(model: &InterestModel): Decimal { model.max_borrow_rate }

/// Create a new interest model
public(package) fun new(
    base_borrow_rate_per_sec: Decimal,
    borrow_rate_on_mid_kink: Decimal,
    mid_kink: Decimal,
    borrow_rate_on_high_kink: Decimal,
    high_kink: Decimal,
    max_borrow_rate: Decimal,
): InterestModel {
    InterestModel {
        base_borrow_rate_per_sec,
        borrow_rate_on_mid_kink,
        mid_kink,
        borrow_rate_on_high_kink,
        high_kink,
        max_borrow_rate,
    }
}

// Return the interest rate under the given utilization rate
// Notice: the interest rate is scaled by a factor, because it's too small to be used directly
public(package) fun calc_interest(
    interest_model: &InterestModel,
    util_rate: Decimal,
): Decimal {
    let borrow_rate_on_mid_kink = interest_model.borrow_rate_on_mid_kink;
    let mid_kink = interest_model.mid_kink;
    let borrow_rate_on_high_kink = interest_model.borrow_rate_on_high_kink;
    let high_kink = interest_model.high_kink;
    let max_borrow_rate = interest_model.max_borrow_rate;
    let base_rate = interest_model.base_borrow_rate_per_sec;
    /* ================== Interest Rate Formula ==================

    Calculate the interest rate with the given utlilization rate of the pool
    if util_rate <= mid_kink:
      interest_rate = (util_rate / mid_kink) * (borrow_rate_on_mid_kink - base_rate) + base_rate
    else if util_rate <= high_kink:
      interest_rate = ((util_rate - mid_kink) / (high_kink - mid_kink)) * (borrow_rate_on_high_kink - borrow_rate_on_mid_kink) + borrow_rate_on_mid_kink
    else:
      interest_rate = ((util_rate - high_kink) / (1 - high_kink)) * (max_borrow_rate - borrow_rate_on_high_kink) + borrow_rate_on_high_kink

    ============================================================== */

    let borrow_rate = if (float::ge(mid_kink, util_rate)) {
        let weight = float::div(util_rate, mid_kink);
        let range = float::sub(borrow_rate_on_mid_kink, base_rate);

        float::add(
            // `weight` is like how far it goes from the starting point within the `range`
            float::mul(weight, range),
            // base borrow rate is the starting point
            base_rate,
        )
    } else if (float::ge(high_kink, util_rate)) {
        let weight = float::div(
            float::sub(util_rate, mid_kink),
            float::sub(high_kink, mid_kink),
        );
        let range = float::sub(borrow_rate_on_high_kink, borrow_rate_on_mid_kink);

        float::add(
            float::mul(weight, range),
            borrow_rate_on_mid_kink,
        )
    } else {
        let weight = float::div(
            float::sub(util_rate, high_kink),
            float::sub(float::from_quotient(1, 1), high_kink),
        );
        let range = float::sub(max_borrow_rate, borrow_rate_on_high_kink);

        float::add(
            float::mul(weight, range),
            borrow_rate_on_high_kink,
        )
    };

    borrow_rate
}

#[test_only]
public struct USDC has drop {}

#[test]
fun interest_rates_test() {
    let interest_model = InterestModel {
        // this borrow rate is not for every sec, cause it just for testing
        base_borrow_rate_per_sec: float::from_quotient(2, 100),
        borrow_rate_on_mid_kink: float::from_quotient(10, 100),
        mid_kink: float::from_quotient(40, 100),
        borrow_rate_on_high_kink: float::from_quotient(50, 100),
        high_kink: float::from_quotient(80, 100),
        max_borrow_rate: float::from_quotient(120, 100),
    };

    // === Low Demand
    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(10, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 4, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(40, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 10, 0);

    // === Optimal Demand
    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(41, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 11, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(50, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 20, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(60, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 30, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(70, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 40, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(80, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 50, 0);

    // === High Demand
    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(85, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 67, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(90, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 85, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(95, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 102, 0);

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(100, 100),
    );
    assert!(shift_decimal(borrow_rate, 2) == 120, 0);
}

#[test]
fun interest_rates_test_2() {
    let interest_model = InterestModel {
        // this borrow rate is not for every sec, cause it just for testing
        base_borrow_rate_per_sec: float::from_quotient(158548959, 1000000000000000000),
        borrow_rate_on_mid_kink: float::from_quotient(3170979198, 1000000000000000000),
        mid_kink: float::from_quotient(80, 100),
        borrow_rate_on_high_kink: float::from_quotient(7927447996, 1000000000000000000),
        high_kink: float::from_quotient(95, 100),
        max_borrow_rate: float::from_quotient(47564687980, 1000000000000000000),
    };

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_quotient(5, 100),
    );
    let expected = float::from_quotient(346825848, 1000000000000000000);

    assert!(borrow_rate.eq(expected));
}

#[test]
fun interest_rates_test_3() {
    let interest_model = InterestModel {
        base_borrow_rate_per_sec: float::from_quotient(317097920, 1000000000000000000),
        borrow_rate_on_mid_kink: float::from_quotient(4756468798, 1000000000000000000),
        mid_kink: float::from_raw(750000000000000000),
        borrow_rate_on_high_kink: float::from_raw(9512937595),
        high_kink: float::from_raw(900000000000000000),
        max_borrow_rate: float::from_raw(47564687980),
    };

    let borrow_rate = calc_interest(
        &interest_model,
        float::from_raw(997448693840969770),
    );
    let expected = float::from_quotient(46593871328, 1000000000000000000);
    std::unit_test::assert_eq!(borrow_rate, expected);
}

#[test_only]
fun shift_decimal(number: Decimal, number_of_shift: u8): u64 {
    number.int_mul(10u64.pow(number_of_shift)) as u64
}

